	/** 
	 * jumpstart the process by instantiating2 Condition
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		conditionId = ConditionService.getConditionInstance()
		.createCondition( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		ConditionService.getConditionInstance()
				.createCondition( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.conditionSubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Condition : " + successValue.getConditionId());
							  if (successValue.getConditionId().equals(conditionId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfConditionList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Condition test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on condition consumed")
					);
			subscriber.conditionSubscribe( conditionId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Condition : " + successValue.getConditionId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfConditionList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on condition for conditionId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Condition. 
	 */
	protected Condition read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Condition" );

		Condition entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Condition with primary key" );
		msg.append( conditionId );
		
		ConditionFetchOneSummary fetchOneSummary = new ConditionFetchOneSummary( conditionId );

		try {
			entity = ConditionService.getConditionInstance().getCondition( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Condition " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Condition.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Condition." );

		StringBuilder msg = new StringBuilder( "Failed to update a Condition : " );        
		Condition entity = read();
		UpdateConditionCommand command = generateUpdateCommand();
		command.setConditionId(entity.getConditionId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Condition." );

			// for use later on...
			conditionId = entity.getConditionId();

			ConditionService proxy = ConditionService.getConditionInstance();  

			proxy.updateCondition( command ).get();

			LOGGER.info( "-- Successfully saved Condition - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + conditionId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Condition.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Condition." );

		Condition entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Condition with id " + conditionId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Condition with id " + conditionId );

			throw e;
		}

		try{
			ConditionService.getConditionInstance().delete( new DeleteConditionCommand( entity.getConditionId() ) ).get();
			LOGGER.info( "-- Successfully deleted Condition with id " + conditionId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Condition with id " + conditionId );

			throw e;
		}
	}

	/**
	 * get all Conditions.
	 */
	protected List<Condition> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Conditions:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Condition : " );        
		List<Condition> collection  = new ArrayList<>();

		try {
			// call the static get method on the ConditionService
			collection = ConditionService.getConditionInstance().getAllCondition();
			assertNotNull( collection, "An Empty collection of Condition was incorrectly returned.");
			
			// Now print out the values
			Condition entity = null;            
			Iterator<Condition> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getConditionId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

